import { EC2Client, DescribeInstancesCommand } from '@aws-sdk/client-ec2';
import { fromTemporaryCredentials } from '@aws-sdk/credential-providers';
import { BadRequestException } from '@nestjs/common';

const region='us-east-1';
const account='600000000042';
const iam=new IAMClient({region});

// replicate getInstanceWithFilters behavior (from awsEc2.ts)
const getInstanceWithFilters=async(region,creds,filters=[])=>{
  try{
    const ec2=new EC2Client({region,credentials:creds});
    let instances=[]; let next;
    do{
      const response=await ec2.send(new DescribeInstancesCommand({NextToken:next,Filters:filters}));
      next=response?.NextToken;
      response.Reservations.forEach(r=>{instances=instances.concat(r.Instances);});
    }while(next);
    return instances;
  }catch(err){
    if(err.Code==='AccessDenied') throw new BadRequestException('Invalid IAM role or external ID');
    else throw new BadRequestException('Error fetching instances');
  }
};

// replicate validateScraperRole
async function validateScraperRole(iamRoleArn, externalId){
  try{
    const sts=new STSClient({region});
    await sts.send(new AssumeRoleCommand({RoleArn:iamRoleArn, RoleSessionName:'meteringco-scraper-validation', ExternalId:externalId}));
  }catch(e){ throw new BadRequestException('Unable to assume the provided IAM role with the supplied external ID');}
  try{
    const creds=fromTemporaryCredentials({params:{RoleArn:iamRoleArn,ExternalId:externalId},clientConfig:{region}});
    await getInstanceWithFilters(region, creds, []);
  }catch(e){ throw new BadRequestException('The provided IAM role cannot read the EC2 instance inventory');}
}

// resolveScraperRole
async function resolveScraperRole(cloudIAM){
  if(!cloudIAM || typeof cloudIAM.iamRoleArn!=='string') throw new BadRequestException('A cloud IAM configuration must specify an iamRoleArn');
  const iamRoleArn=cloudIAM.iamRoleArn.trim();
  if(iamRoleArn==='') return {iamRoleArn:''};
  const externalId=cloudIAM.externalId?cloudIAM.externalId:undefined;
  await validateScraperRole(iamRoleArn, externalId);
