  try{ const r=await fn(); if(shouldThrow){console.log('FAIL',label,'expected throw, got', JSON.stringify(r));} else {console.log('PASS',label,'->',JSON.stringify(r));} }
  catch(e){ if(shouldThrow){ const ok=!msgContains||(e.message&&e.message.includes(msgContains)); console.log(ok?'PASS':'FAIL',label,'threw:',e.message);} else {console.log('FAIL',label,'unexpected throw:',e.message);} }
}

async function main(){
  const base=`arn:aws:iam::${account}:role/`;
  await createRole('good-full', undefined, true);       // assumable + ec2
  await createRole('good-ext', 'ext-secret', true);     // assumable w/ ext + ec2
  await createRole('no-ec2', undefined, false);         // assumable but no ec2 perm

  // 1. valid role, no external id
  await expect('valid role (no extId)', ()=>resolveScraperRole({iamRoleArn:base+'good-full'}), false);
  // 2. valid role with external id
  await expect('valid role + correct extId', ()=>resolveScraperRole({iamRoleArn:base+'good-ext',externalId:'ext-secret'}), false);
  // 3. role requiring extId, wrong extId -> assume fails
  await expect('role + wrong extId', ()=>resolveScraperRole({iamRoleArn:base+'good-ext',externalId:'wrong'}), true, 'assume');
  // 4. role requiring extId, no extId -> assume fails
  await expect('role needs extId, none given', ()=>resolveScraperRole({iamRoleArn:base+'good-ext'}), true, 'assume');
  // 5. nonexistent role -> assume fails
  await expect('nonexistent role', ()=>resolveScraperRole({iamRoleArn:base+'does-not-exist'}), true, 'assume');
  // 6. role assumable but no ec2 read -> inventory check fails
  await expect('role no ec2 perm', ()=>resolveScraperRole({iamRoleArn:base+'no-ec2'}), true, 'inventory');
  // 7. blank role -> disconnect, clears externalId
  await expect('blank role disconnect', ()=>resolveScraperRole({iamRoleArn:'',externalId:'stale'}), false);
  // 8. settings block naming no role -> invalid
  await expect('no role key', ()=>resolveScraperRole({externalId:'x'}), true, 'must specify an iamRoleArn');
  // 9. empty object -> invalid
  await expect('empty cloudIAM', ()=>resolveScraperRole({}), true, 'must specify an iamRoleArn');
}
main();
